-- R4 clarification requests tied to a normalized vendor response.

ALTER TABLE public.rfp_clarifications
  ADD COLUMN response_normalization_id uuid,
  ADD COLUMN deadline_at timestamptz,
  ADD COLUMN response_reference text,
  ADD COLUMN asked_at timestamptz NOT NULL DEFAULT now(),
  ADD COLUMN answered_at timestamptz;
CREATE INDEX rfp_clarifications_response_idx ON public.rfp_clarifications (organization_id, response_normalization_id, status);
ALTER TABLE public.rfp_clarifications
  ADD CONSTRAINT rfp_clarifications_response_scope_fk FOREIGN KEY (organization_id, response_normalization_id) REFERENCES public.rfp_response_normalizations (organization_id, id) ON DELETE RESTRICT,
  ADD CONSTRAINT rfp_clarifications_response_reference_ck CHECK (response_reference IS NULL OR length(btrim(response_reference)) BETWEEN 1 AND 500),
  ADD CONSTRAINT rfp_clarifications_deadline_ck CHECK (deadline_at IS NULL OR deadline_at >= asked_at);

CREATE OR REPLACE FUNCTION public.mmhr_record_rfp_response_clarification(payload jsonb, correlation_id uuid, idempotency_key uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = ''
AS $$
DECLARE context record; receipt jsonb; clarification public.rfp_clarifications%ROWTYPE; normalization public.rfp_response_normalizations%ROWTYPE; version_row public.rfp_versions%ROWTYPE; v_action text; v_id uuid; v_org uuid; v_actor uuid; v_rfp_id uuid; v_version integer; v_normalization_id uuid; v_deadline timestamptz; v_reference text; v_question text; v_answer text; v_change text; v_decision text;
BEGIN
  IF jsonb_typeof(payload) <> 'object' OR coalesce(payload->>'action','') NOT IN ('ask','respond') OR correlation_id IS NULL OR idempotency_key IS NULL OR coalesce(payload->>'clarificationId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'normalizationId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'organizationId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'rfpId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'actorIdentityId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'version','') !~ '^[1-9][0-9]{0,3}$' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid RFP response clarification input'; END IF;
  v_action := payload->>'action'; v_id := (payload->>'clarificationId')::uuid; v_normalization_id := (payload->>'normalizationId')::uuid; v_org := (payload->>'organizationId')::uuid; v_rfp_id := (payload->>'rfpId')::uuid; v_actor := (payload->>'actorIdentityId')::uuid; v_version := (payload->>'version')::integer; v_question := nullif(btrim(payload->>'question'),''); v_answer := nullif(btrim(payload->>'answer'),''); v_change := nullif(btrim(payload->>'changeSummary'),''); v_decision := payload->>'decision'; v_reference := nullif(btrim(payload->>'responseReference'),''); v_deadline := nullif(payload->>'deadlineAt','')::timestamptz;
  IF v_action = 'ask' AND (v_question IS NULL OR length(v_question) > 5000) THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid clarification question'; END IF;
  IF v_action = 'respond' AND (v_answer IS NULL OR length(v_answer) > 5000 OR v_decision NOT IN ('accepted','rejected','deferred')) THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid clarification response'; END IF;
  SELECT * INTO context FROM mmhr_private.r1_start_security_command('workspace.access', v_org, 'Record RFP response clarification', correlation_id, idempotency_key); IF v_actor <> context.actor_identity_id THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Security command denied'; END IF;
  receipt := mmhr_private.r1_checked_receipt(context.actor_identity_id, 'r4.rsp.clarification', idempotency_key, payload); IF receipt IS NOT NULL THEN SELECT * INTO clarification FROM public.rfp_clarifications c WHERE c.id = (receipt->>'entity_id')::uuid AND c.organization_id = v_org; IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Security command denied'; END IF; RETURN jsonb_build_object('clarificationId', clarification.id, 'organizationId', clarification.organization_id, 'rfpId', v_rfp_id, 'version', v_version, 'normalizationId', clarification.response_normalization_id, 'status', clarification.status, 'decision', clarification.decision, 'deadlineAt', clarification.deadline_at, 'responseReference', clarification.response_reference, 'outcomeCode', 'replayed', 'correlationId', correlation_id); END IF;
  SELECT n.* INTO normalization FROM public.rfp_response_normalizations n WHERE n.id = v_normalization_id AND n.organization_id = v_org; IF NOT FOUND OR normalization.state NOT IN ('pending','reviewed','approved') THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='RFP response clarification association denied'; END IF;
  SELECT r.* INTO version_row FROM public.rfp_versions r WHERE r.id = normalization.rfp_version_id AND r.organization_id = v_org AND r.rfp_id = v_rfp_id AND r.version = v_version AND r.status IN ('approved','distributed'); IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='RFP response clarification association denied'; END IF;
  IF v_action = 'ask' THEN INSERT INTO public.rfp_clarifications (id, organization_id, rfp_version_id, response_normalization_id, question, deadline_at, asked_by_identity_id, asked_at, status, decision) VALUES (v_id, v_org, version_row.id, normalization.id, v_question, v_deadline, v_actor, clock_timestamp(), 'pending', 'pending') RETURNING * INTO clarification;
  ELSE SELECT * INTO clarification FROM public.rfp_clarifications c WHERE c.id = v_id AND c.organization_id = v_org AND c.response_normalization_id = normalization.id FOR UPDATE; IF NOT FOUND OR clarification.status <> 'pending' THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='RFP response clarification transition denied'; END IF; UPDATE public.rfp_clarifications SET answer = v_answer, change_summary = v_change, decision = v_decision, status = 'answered', answered_by_identity_id = v_actor, answered_at = clock_timestamp(), response_reference = v_reference WHERE id = v_id AND organization_id = v_org RETURNING * INTO clarification; END IF;
  PERFORM mmhr_private.r1_finish_security_command(context.actor_identity_id, 'r4.rsp.clarification', 'rsp.clarification', 'rfp_clarification', clarification.id, v_org, 'Record RFP response clarification', correlation_id, idempotency_key, payload, jsonb_build_object('status', 'pending', 'version', version_row.version), jsonb_build_object('status', CASE WHEN v_action = 'ask' THEN 'pending' ELSE 'completed' END, 'version', version_row.version), context.authorization_time);
  RETURN jsonb_build_object('clarificationId', clarification.id, 'organizationId', clarification.organization_id, 'rfpId', version_row.rfp_id, 'version', version_row.version, 'normalizationId', clarification.response_normalization_id, 'status', clarification.status, 'decision', clarification.decision, 'deadlineAt', clarification.deadline_at, 'responseReference', clarification.response_reference, 'outcomeCode', 'recorded', 'correlationId', correlation_id);
END
$$;
REVOKE ALL ON FUNCTION public.mmhr_record_rfp_response_clarification(jsonb, uuid, uuid) FROM PUBLIC, anon, authenticated, service_role, mmhr_worker;
GRANT EXECUTE ON FUNCTION public.mmhr_record_rfp_response_clarification(jsonb, uuid, uuid) TO authenticated;
